PartGrid_ColumnDispatch:
	ldda32 xhl, (3182)
	ldda32 xbc, (3186)
	cp a, 0x1e
	jr nc, PartGrid_CopyHLtoBC
	cp a, 0xa
	ret c
	sub a, 0xa
	extz wa
	div a, 0x3
	extz wa
	cps wa, 0
	jr mi, PartGrid_CopyHLtoBC
	cps wa, 6
	jr gt, PartGrid_CopyHLtoBC
	add wa, wa
	lda_24 xix, (MSP_Default_GroupOffsetA)
	ldw_sri WA, 0x07, 0xf0, 0xe0
	lda_24 xix, (PartGrid_ColumnJumpTable)
	jp_ind 8, 0x07, 0xf0, 0xe0

PartGrid_ColumnJumpTable:
	ldda32	xhl, (3190)
	jr	38
	ldda32	xhl, (3194)
	jr	32
	ldda32	xhl, (3198)
	jr	26
	ldda32	xhl, (3202)
	jr	20
	ldda32	xhl, (3206)
	jr	14
	ldda32	xhl, (3210)
	jr	8
	ldda32	xhl, (3214)
	jr	t, 0x02

PartGrid_CopyHLtoBC:
	ld xhl, xbc
	ret

Util_FrameSetup10:
	lda xsp, (xsp - 10)
	ld (xsp + 4), e
	ld (xsp + 6), c
	ld (xsp + 8), a
	ld a, (xsp + 8)
	extz wa
	calr PartGrid_ColumnDispatch
	ld (xsp), xhl
	cp (xsp + 8), 0x1e
	jr c, FrameSetup_AdjustGE1E
	submi8 (xsp + 8), 0x1e
	jr FrameSetup_ComputeGridIndex

FrameSetup_AdjustGE1E:
	cp (xsp + 8), 0xa
	jr c, FrameSetup_ComputeGridIndex
	submi8 (xsp + 8), 0xa
	ld a, (xsp + 8)
	extz wa
	div a, 0x3
	ld (xsp + 8), w

FrameSetup_ComputeGridIndex:
	ld c, (xsp + 8)
	extz bc
	ld a, (xsp + 6)
	extz wa
	muls wa, 0x3
	add wa, bc
	lda_24 xbc, (MSP_Default_ChannelMap)
	ldb_sri A, 0x07, 0xe4, 0xe0
	ld e, (xsp + 4)
	cp (xsp + 4), 0x4
	jr z, FrameSetup_SpecialCase4
	extz wa
	muls wa, 0x60
	ld bc, wa
	add bc, 0x60
	ld xwa, (xsp)
	exts xbc
	add xbc, xwa
	cps e, 3
	jr z, FrameSetup_RowOffset3
	cps e, 2
	jr z, FrameSetup_RowOffset2
	cps e, 1
	jr z, FrameSetup_RowOffset1
	cps e, 0
	jr nz, FrameSetup_PackResult
	ld l, (xbc + 24)
	ld xwa, 0x19
	jr PartGrid_ByteOffsetLoop

FrameSetup_RowOffset1:
	ld l, (xbc + 32)
	ld xwa, 0x21
	jr PartGrid_ByteOffsetLoop

FrameSetup_RowOffset2:
	ld l, (xbc + 40)
	ld xwa, 0x29
	jr PartGrid_ByteOffsetLoop

FrameSetup_RowOffset3:
	ld l, (xbc + 48)
	ld xwa, 0x31

PartGrid_ByteOffsetLoop:
	add xbc, xwa
	ld a, (xbc)
	jr FrameSetup_PackResult

FrameSetup_SpecialCase4:
	extz wa
	muls wa, 0x60
	ld bc, wa
	add bc, 0x60
	ld xwa, (xsp)
	stb_dri W, 0x07, 0xe0, 0xe4
	ld l, (xwa + 56)
	ld a, (xwa + 57)

FrameSetup_PackResult:
	ld c, l
	extz bc
	extz wa
	sll wa, 8
	or wa, bc
	ld hl, wa
	lda xsp, (xsp + 10)
	ret

PartGrid_OperationsBlock:
	lda	xsp, (xsp-14)
	ld	(xsp+8), e
	ld	(xsp+10), c
	ld	(xsp+12), a
	ld	a, (xsp+12)
	extz	wa
	calr	65203
	ld	(xsp+4), xhl
	cp	(xsp+12), 30
	jr	c, 6
	.byte 0x8f
	incf
	push	xde
	.byte 0x1e
	jr	21
	cp	(xsp+12), 10
	jr	c, 15
	.byte 0x8f
	incf
	push	xde
	.byte 0x0a
	ld	a, (xsp+12)
	extz	wa
	div	a, 3
	ld	(xsp+12), w
	ld	c, (xsp+12)
	extz	bc
	ld	a, (xsp+10)
	extz	wa
	muls	wa, 3
	add	wa, bc
	lda_24	xbc, (MSP_Default_ChannelMap)
	ld_rrb	a, xbc, wa
	ld	(xsp+2), a
	ld	bc, (xsp+18)
	ld	de, bc
	ldb	d, 0
	srl	bc, 8
	ld	(xsp), c
	ld	a, (xsp+2)
	extz	wa
	muls	wa, 96
	ld	bc, wa
	add	bc, 96
	ld	xwa, (xsp+4)
	exts	xbc
	add	xbc, xwa
	cp	(xsp+8), 4
	jr	z, 64
	cp	(xsp+8), 3
	jr	z, 48
	cp	(xsp+8), 2
	jr	z, 32
	cp	(xsp+8), 1
	jr	z, 16
	cp	(xsp+8), 0
	jr	nz, 54
	ld	(xbc+24), e
	ld	xwa, 25
	jr	38
	.byte 0xb9
	.asciz " E@!"
	nop
	nop
	jr	28
	.byte 0xb9
	.asciz "(E@)"
	nop
	nop
	jr	18
	ld	(xbc+48), e
	ld	xwa, 49
	jr	8
	ld	(xbc+56), e
	ld	xwa, 57
	add	xbc, xwa
	ld	a, (xsp)
	ld	(xbc), a
	lda	xsp, (xsp+14)
	retd	2

; PartGrid column dispatch end
PartGrid_ColumnDispatch_End:
	lds wa, 0
	jr PartGrid_ColumnDispatch_Default

; PartGrid column dispatch default case
PartGrid_ColumnDispatch_Default:
	dec 2, xsp
	push xiz
	ld (xsp + 4), a
	ldiw_erp 0xfa, 0

PartGrid_DefaultLoop_Outer:
	stw_erp WA, 0xfa
	extz xwa
	ld xbc, xwa
	add xbc, xbc
	add xbc, xwa
	sll xbc, 5
	add xbc, 0x60
	addda32 xbc, 3186
	ld wa, (xbc)
	ld c, (xsp + 4)
	extz bc
	calr Pack12BitValueWithBank
	ld wa, hl
	stw_erp BC, 0xfa
	extz xbc
	ld xde, xbc
	add xde, xde
	add xde, xbc
	sll xde, 5
	add xde, 0x60
	addda32 xde, 3186
	ld (xde), wa
	lds iz, 2

PartGrid_DefaultLoop_Inner:
	ld bc, iz
	extz xbc
	add xbc, xbc
	stw_erp WA, 0xfa
	extz xwa
	ld xde, xwa
	add xde, xde
	add xde, xwa
	sll xde, 5
	add xde, xbc
	addda32 xde, 3186
	ld wa, (xde + 96)
	ld c, (xsp + 4)
	extz bc
	calr Pack12BitValueWithBank
	ld wa, hl
	ld de, iz
	extz xde
	add xde, xde
	stw_erp BC, 0xfa
	extz xbc
	ld xhl, xbc
	add xhl, xhl
	add xhl, xbc
	sll xhl, 5
	add xhl, xde
	addda32 xhl, 3186
	ld (xhl + 96), wa
	inc 1, iz
	cps iz, 5
	jr ule, PartGrid_DefaultLoop_Inner
	inc1w_erp 0xfa
	cp_erpw 0xfa, 0x1d, 0x00
	jrl ule, PartGrid_DefaultLoop_Outer
	ldiw_erp 0xfa, 0

; NoteEventBuffer CopyToSlot dispatch (7-entry, table 0xe16128)
NoteEvent_CopyToSlot:
	stw_erp WA, 0xfa
	extz xwa
	sll xwa, 8
	add xwa, 0x1400
	addda32 xwa, 3186
	ld wa, (xwa + 1)
	ld c, (xsp + 4)
	extz bc
	calr Pack12BitValueWithBank
	ld wa, hl
	stw_erp BC, 0xfa
	extz xbc
	sll xbc, 8
	add xbc, 0x1400
	ld xde, xbc
	addda32 xde, 3186
	ld (xde + 1), wa
	addda32 xbc, 3186
	ld wa, (xbc + 3)
	ld c, (xsp + 4)
	extz bc
	calr Pack12BitValueWithBank
	ld wa, hl
	stw_erp BC, 0xfa
	extz xbc
	sll xbc, 8
	add xbc, 0x1400
	addda32 xbc, 3186
	ld (xbc + 3), wa
	inc1w_erp 0xfa
	cp_erpw 0xfa, 0x53, 0x01
	jr ule, NoteEvent_CopyToSlot
	pop xiz
	inc 2, xsp
	ret

Pack12BitValueWithBank:
	ld hl, wa
	cp hl, 0xffff
	ret z
	and hl, 0xfff
	extz bc
	sll bc, 12
	or hl, bc
	ret

; NoteEventBuffer Store dispatch (7-entry, table 0xe16136)
NoteEvent_Store:
	extz wa
	lda_24 xbc, (MSP_Default_ChannelMap_0x1E)
	ldb_sri L, 0x07, 0xe4, 0xe0
	ret

NoteEventBuffer_CopyToSlot:
	ld c, a
	ldda32 xwa, (3186)
	extz bc
	dec 1, bc
	cps bc, 0
	jr lt, NoteEvent_CopyCommon
	cps bc, 6
	jr gt, NoteEvent_CopyCommon
	add bc, bc
	lda_24 xix, (MSP_Default_GroupOffsetB)
	ldw_sri BC, 0x07, 0xf0, 0xe4
	lda_24 xix, (NOTE_EVENT_DISPATCH_1)
	jp_ind 8, 0x07, 0xf0, 0xe4
; Note event buffer copy dispatch - 7 cases (BC 0-6)
; Selects destination buffer pointer based on case, then copies 46080 bytes
; Offset table at 0xe16128
NOTE_EVENT_DISPATCH_1:
	ldda32 xbc, (3190); Case 0: Load dest pointer
	jr NOTE_EVENT_COPY_COMMON
	ldda32 xbc, (3194); Case 1: Load dest pointer
	jr NOTE_EVENT_COPY_COMMON
	ldda32 xbc, (3198); Case 2: Load dest pointer
	jr NOTE_EVENT_COPY_COMMON
	ldda32 xbc, (3202); Case 3: Load dest pointer
	jr NOTE_EVENT_COPY_COMMON
	ldda32 xbc, (3206); Case 4: Load dest pointer
	jr NOTE_EVENT_COPY_COMMON
	ldda32 xbc, (3210); Case 5: Load dest pointer
	jr NOTE_EVENT_COPY_COMMON
	ldda32 xbc, (3214); Case 6: Load dest pointer (falls through)
NOTE_EVENT_COPY_COMMON:	; F1717D - Common handler
	ld xiy, xbc	; XIY = destination pointer
	ld xix, xwa	; XIX = source pointer
	ldw bc, 0xb400	; BC = 0xb400 byte count
	ldirw	; Block copy words

; NoteEventBuffer copy common handler
NoteEvent_CopyCommon:
	jrl PartGrid_ColumnDispatch_End

NoteEventBuffer_Store:
	lda xsp, (xsp - 10)
	ld (xsp + 8), a
	ld a, (xsp + 8)
	extz wa
	calr PartGrid_ColumnDispatch_Default
	ldda32 xwa, (3186)
	ld (xsp), xwa
	ld a, (xsp + 8)
	extz wa
	dec 1, wa
	cps wa, 0
	jrl lt, NoteEvent_StoreCommon
	cps wa, 6
	jrl gt, NoteEvent_StoreCommon
	add wa, wa
	lda_24 xix, (MSP_Default_VarSize)
	ldw_sri WA, 0x07, 0xf0, 0xe0
	lda_24 xix, (NOTE_EVENT_DISPATCH_2)
	jp_ind 8, 0x07, 0xf0, 0xe0
; Note event dispatch table 2
; 7 cases (WA 0-6), offset table at 0xe16136
NOTE_EVENT_DISPATCH_2:
	ldda32 xwa, (3190)
	ld (xsp + 4), xwa
	jrl Flash_WriteSectorWithMirrorCopy
NOTE_EVENT_DISPATCH_2b:
	ldda32 xwa, (3194)
	ld (xsp + 4), xwa

Flash_SectorWriteExecute:
	ld xwa, (xsp)
	stb_dri A, 0xe1, 0x00, 0x68
	ld xwa, (xsp + 4)
	stb_dri B, 0xe1, 0x00, 0x68
	lds wa, 1
	call Flash_EraseSectorAndWrite
	ld xiy, (xsp + 4)
	sub xiy, 0x9800
	ld xwa, (xsp)
	stb_dri B, 0xe1, 0x00, 0x68
	ld xix, xde
	ldw bc, 0x8000
	ldirw
	ld xbc, (xsp)

Flash_CopyMirrorLoop:
	ld xhl, xbc
	add xhl, 0x10000
	ldb_spi A, 0xe4
	ld (xhl), a
	cp xbc, xde
	jr c, Flash_CopyMirrorLoop
	ld xwa, (xsp)
	stb_dri A, 0xe1, 0x00, 0x68
	ld xde, (xsp + 4)
	sub xde, 0x9800
	lds wa, 1
	jr Flash_EraseAndWriteFinal
	ldda32 xwa, (3198)
	ld (xsp + 4), xwa
	jr Flash_WriteSectorWithMirrorCopy
	ldda32 xwa, (3202)
	ld (xsp + 4), xwa
	jr Flash_SectorWriteExecute
	ldda32 xwa, (3206)
	ld (xsp + 4), xwa
	jr Flash_WriteSectorWithMirrorCopy
	ldda32 xwa, (3210)
	ld (xsp + 4), xwa
	jr Flash_SectorWriteExecute
	ldda32 xwa, (3214)
	ld (xsp + 4), xwa
	jr Flash_WriteSectorWithMirrorCopy

; NoteEventBuffer store common handler
NoteEvent_StoreCommon:
	cps a, 0
	jrl nz, Flash_SectorWriteExecute

Flash_WriteSectorWithMirrorCopy:
	lds wa, 1
	ld xbc, (xsp)
	ld xde, (xsp + 4)
	call Flash_EraseSectorAndWrite
	ld xiy, (xsp + 4)
	add xiy, 0x10000
	ld xwa, (xsp)
	ld xix, xwa
	ldw bc, 0x8000
	ldirw
	ld xwa, (xsp)
	add xwa, 0x10000
	ld xbc, xwa
	stb_dri B, 0xe1, 0x00, 0x68

Flash_CopyReverseMirrorLoop:
	ld xhl, xbc
	add xhl, 0xffff0000
	ldb_spi A, 0xe4
	ld (xhl), a
	cp xbc, xde
	jr c, Flash_CopyReverseMirrorLoop
	ld xde, (xsp + 4)
	add xde, 0x10000
	lds wa, 1
	ld xbc, (xsp)

Flash_EraseAndWriteFinal:
	call Flash_EraseSectorAndWrite
	lda xsp, (xsp + 10)
	ret

Flash_StoreBaseAndInitAccPatch:
	ldda32	xwa, (3186)
	stda32	(14610), xwa
	jp	16166403
