VoiceParam_ComputeOffset:
	ld e, a
	cp e, 0x28
	jr nc, VoiceParam_SubtractBase
	ld xhl, 0x10
	jr VoiceParam_AddOffset

VoiceParam_SubtractBase:
	sub e, 0x28
	ld xhl, 0x50

VoiceParam_AddOffset:
	extz de
	add hl, de
	ldda32 xwa, (3222)
	lda_dri XHL, 0x07, 0xe0, 0xec
	ret

DualVoice_ScanAllColumns:
	dec 2, xsp
	pushw_erp 0xfa
	ld (xsp + 2), a
	calr SlotTable_InitBank1748
	ldib_erp 0xfb, 0

DualVoice_ScanColumnLoop:
	ld a, (xsp + 2)
	extz wa
	stb_erp C, 0xfb
	extz bc
	lds de, 0
	calr Util_FrameSetup10
	ld wa, hl
	ld bc, wa
	and bc, 0x700
	cp bc, 0x600
	jr z, DualVoice_StoreBankMatch
	cp bc, 0x500
	jr nz, DualVoice_ScanRow1

DualVoice_StoreBankMatch:
	stda16 (1748), xwa

DualVoice_ScanRow1:
	ld a, (xsp + 2)
	extz wa
	stb_erp C, 0xfb
	extz bc
	lds de, 1
	calr Util_FrameSetup10
	ld wa, hl
	ld bc, wa
	and bc, 0xff
	cp bc, 0x80
	call_24 nc, SlotTable_Insert1748
	ld a, (xsp + 2)
	extz wa
	stb_erp C, 0xfb
	extz bc
	lds de, 2
	calr Util_FrameSetup10
	ld wa, hl
	ld bc, wa
	and bc, 0xff
	cp bc, 0x80
	call_24 nc, SlotTable_Insert1748
	ld a, (xsp + 2)
	extz wa
	stb_erp C, 0xfb
	extz bc
	lds de, 3
	calr Util_FrameSetup10
	ld wa, hl
	ld bc, wa
	and bc, 0xff
	cp bc, 0x80
	call_24 nc, SlotTable_Insert1748
	ld a, (xsp + 2)
	extz wa
	stb_erp C, 0xfb
	extz bc
	lds de, 4
	calr Util_FrameSetup10
	ld wa, hl
	ld bc, wa
	and bc, 0xff
	cp bc, 0x80
	call_24 nc, SlotTable_Insert1748
	inc1b_erp 0xfb
	cp_erpb 0xfb, 0x0a
	jrl c, DualVoice_ScanColumnLoop
	popw_erp 0xfa
	inc 2, xsp
	ret

DualVoice_ScanAllColumnsAlt:
	dec 2, xsp
	pushw_erp 0xfa
	ld (xsp + 2), a
	calr SlotTable_InitBank1850
	ldib_erp 0xfb, 0

DualVoice_ScanColumnLoopAlt:
	ld a, (xsp + 2)
	extz wa
	stb_erp C, 0xfb
	extz bc
	lds de, 0
	calr Util_FrameSetup10
	ld wa, hl
	ld bc, wa
	and bc, 0x700
	cp bc, 0x600
	jr z, DualVoice_StoreBankMatchAlt
	cp bc, 0x500
	jr nz, DualVoice_ScanRow1Alt

DualVoice_StoreBankMatchAlt:
	stda16 (1850), xwa

DualVoice_ScanRow1Alt:
	ld a, (xsp + 2)
	extz wa
	stb_erp C, 0xfb
	extz bc
	lds de, 1
